script:
frappe.ui.form.on('Joueur', {
  date_naissance: calc_age,
  date_debut_contrat: calc_duree,
  date_fin_contrat: calc_duree,
  refresh: function(frm){
    calc_age(frm);
    calc_duree(frm);
    if(!frm.is_new() && frm.doc.name && frm.doc.matricule !== frm.doc.name){
      frm.set_value('matricule', frm.doc.name);
    }
  },
  after_save: function(frm){
    if(frm.doc.matricule !== frm.doc.name){
      frappe.db.set_value('Joueur', frm.doc.name, 'matricule', frm.doc.name);
    }
  }
});
function calc_age(frm){
  if(frm.doc.date_naissance){
    let d = frappe.datetime.str_to_obj(frm.doc.date_naissance);
    let now = new Date();
    let age = now.getFullYear() - d.getFullYear();
    let m = now.getMonth() - d.getMonth();
    if(m < 0 || (m===0 && now.getDate() < d.getDate())) age--;
    frm.set_value('age', age);
  }
}
function calc_duree(frm){
  if(frm.doc.date_debut_contrat && frm.doc.date_fin_contrat){
    let deb = frappe.datetime.str_to_obj(frm.doc.date_debut_contrat);
    let fin = frappe.datetime.str_to_obj(frm.doc.date_fin_contrat);
    let mois = (fin.getFullYear()-deb.getFullYear())*12 + (fin.getMonth()-deb.getMonth());
    if(fin.getDate() >= deb.getDate()) { /* mois complet */ } else { mois -= 1; }
    if(mois < 0) mois = 0;
    frm.set_value('duree_contrat', mois);
  }
}

frappe.ui.form.on('Match', {
  score_novakin: set_resultat,
  score_adversaire: set_resultat,
  statut: function(frm){ if(frm.doc.statut==='Joué') set_resultat(frm); }
});
function set_resultat(frm){
  if(frm.doc.score_novakin===undefined || frm.doc.score_adversaire===undefined) return;
  let a = frm.doc.score_novakin||0, b = frm.doc.score_adversaire||0;
  let r = a>b ? 'Victoire' : (a===b ? 'Nul' : 'Défaite');
  frm.set_value('resultat', r);
}

function nfc_load_qr(){return new Promise(function(res){if(window.QRCode){res(true);return;}var s=document.createElement('script');s.src='https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js';s.onload=function(){res(true);};s.onerror=function(){res(false);};document.head.appendChild(s);});}
async function nfc_gen_qr(t){var ok=await nfc_load_qr();if(!ok||!window.QRCode)return '';var tmp=document.createElement('div');new QRCode(tmp,{text:t,width:110,height:110,correctLevel:QRCode.CorrectLevel.M});await new Promise(function(r){setTimeout(r,250);});var el=tmp.querySelector('img')||tmp.querySelector('canvas');if(!el)return '';return el.tagName==='IMG'?el.src:el.toDataURL();}

frappe.ui.form.on('Courrier Entrant', {
  refresh: function(frm){
    render_preview(frm);
    if(frm.doc.statut === 'Clôturé' && !frm.is_new()){
      frm.disable_save();
      frm.set_read_only();
      frm.dashboard.set_headline('<span style="color:#c8102e">🔒 Courrier CLÔTURÉ — lecture seule</span>');
    }
    if(!frm.is_new()){
      frm.add_custom_button('🧾 Accusé de Réception', function(){
        window.open('/printview?doctype=Courrier%20Entrant&name='+encodeURIComponent(frm.doc.name)+'&format=Accus%C3%A9%20de%20R%C3%A9ception&no_letterhead=1','_blank');
      });
    }
  },
  scan_courrier: function(frm){ render_preview(frm); },
  before_workflow_action: async function(frm){
    var action = frm.selected_workflow_action;
    if(!action) return;
    try{
      await frappe.call({method:'frappe.client.insert',args:{doc:{
        doctype:'Suivi Courrier', parenttype:'Courrier Entrant', parentfield:'historique', parent:frm.doc.name,
        date_action: frappe.datetime.now_datetime(), action: action, par: frappe.session.user
      }}});
    }catch(e){ console.error('hist err', e); }
  },
  after_save: async function(frm){
    var url = frappe.urllib.get_full_url('/app/courrier-entrant/'+encodeURIComponent(frm.doc.name));
    var d = await nfc_gen_qr(url);
    if(d && d !== frm.doc.qr_code){ await frappe.db.set_value('Courrier Entrant', frm.doc.name, 'qr_code', d); }
  }
});

function render_preview(frm){
  var w = frm.get_field('apercu_html'); if(!w) return;
  var url = frm.doc.scan_courrier;
  if(!url){ w.$wrapper.html('<div style="padding:30px;text-align:center;color:#999;border:1px dashed #ccc;border-radius:8px;">Aucun document téléversé.</div>'); return; }
  var lo = url.toLowerCase(); var html;
  if(lo.indexOf('.pdf')>=0){ html='<iframe src="'+url+'" style="width:100%;height:520px;border:1px solid #ddd;border-radius:8px;"></iframe>'; }
  else if(lo.match(/\.(png|jpg|jpeg|gif|webp|bmp)/)){ html='<div style="border:1px solid #ddd;border-radius:8px;padding:8px;text-align:center;background:#fafafa;"><img src="'+url+'" style="max-width:100%;max-height:600px;border-radius:4px;"/></div>'; }
  else { html='<div style="padding:20px;border:1px solid #ddd;border-radius:8px;"><a href="'+url+'" target="_blank">📎 Ouvrir le document</a></div>'; }
  w.$wrapper.html(html);
}

function nfc_load_qr(){return new Promise(function(res){if(window.QRCode){res(true);return;}var s=document.createElement('script');s.src='https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js';s.onload=function(){res(true);};s.onerror=function(){res(false);};document.head.appendChild(s);});}
async function nfc_gen_qr(t){var ok=await nfc_load_qr();if(!ok||!window.QRCode)return '';var tmp=document.createElement('div');new QRCode(tmp,{text:t,width:110,height:110,correctLevel:QRCode.CorrectLevel.M});await new Promise(function(r){setTimeout(r,250);});var el=tmp.querySelector('img')||tmp.querySelector('canvas');if(!el)return '';return el.tagName==='IMG'?el.src:el.toDataURL();}

frappe.ui.form.on('Courrier Sortant', {
  refresh: function(frm){
    if(frm.doc.statut === 'Archivé' && !frm.is_new()){
      frm.dashboard.set_headline('📁 Courrier archivé');
    }
  },
  before_workflow_action: async function(frm){
    var action = frm.selected_workflow_action;
    if(!action) return Promise.resolve();
    if(action === 'Soumettre pour validation'){
      if(!frm.doc.validateur){
        frappe.throw('Veuillez renseigner le <b>Validateur</b> avant de soumettre pour validation.');
        return Promise.reject();
      }
      if(!frm.doc.corps || frm.doc.corps.replace(/<[^>]*>/g,'').trim()===''){
        frappe.throw('Le <b>corps du courrier</b> ne peut pas être vide.');
        return Promise.reject();
      }
      if(!frm.doc.destinataire){
        frappe.throw('Le <b>destinataire</b> est obligatoire.');
        return Promise.reject();
      }
    }
    try{
      await frappe.call({method:'frappe.client.insert',args:{doc:{
        doctype:'Suivi Courrier', parenttype:'Courrier Sortant', parentfield:'historique', parent:frm.doc.name,
        date_action: frappe.datetime.now_datetime(), action: action, par: frappe.session.user
      }}});
    }catch(e){ console.error('hist err', e); }
  },
  after_save: async function(frm){
    var url = frappe.urllib.get_full_url('/app/courrier-sortant/'+encodeURIComponent(frm.doc.name));
    var d = await nfc_gen_qr(url);
    if(d && d !== frm.doc.qr_code){ await frappe.db.set_value('Courrier Sortant', frm.doc.name, 'qr_code', d); }
  }
});

frappe.ui.form.on('Courrier Sortant', {
  type_courrier: function(frm){ apply_template(frm); }
});
function apply_template(frm){
  var t = frm.doc.type_courrier;
  var body_empty = !frm.doc.corps || frm.doc.corps.replace(/<[^>]*>/g,'').trim()==='';
  var templates = {
    'Attestation': {
      salutation: 'À qui de droit,',
      corps: '<p>Nous, soussignés, NOVAKIN FOOTBALL CLUB, attestons par la présente que <b>[Nom &amp; Prénom]</b>, [fonction / qualité], est [membre / joueur / employé] de notre club depuis le <b>[date]</b>.</p><p>La présente attestation est délivrée à l\'intéressé(e) pour servir et valoir ce que de droit.</p>',
      formule: 'En foi de quoi, la présente attestation lui est délivrée pour faire valoir ce que de droit.',
      fonction_sig: 'Le Secrétaire Général'
    },
    'Convocation': {
      salutation: 'Cher membre,',
      corps: '<p>Par la présente, vous êtes prié(e) de bien vouloir vous présenter le <b>[date]</b> à <b>[heure]</b>, au <b>[lieu]</b>, à l\'effet de participer à <b>[objet : réunion / séance d\'entraînement / audition]</b>.</p><p>Votre présence est <b>obligatoire</b>. En cas d\'empêchement majeur, vous voudrez bien en informer le secrétariat dans les meilleurs délais.</p>',
      formule: 'Comptant sur votre ponctualité, veuillez agréer nos salutations sportives.',
      fonction_sig: 'La Direction'
    },
    'Invitation': {
      salutation: 'Madame, Monsieur,',
      corps: '<p>Le NOVAKIN FOOTBALL CLUB a l\'honneur de vous convier à <b>[événement]</b> qui se tiendra le <b>[date]</b> à <b>[heure]</b>, au <b>[lieu]</b>.</p><p>Votre présence contribuera à l\'éclat de cet événement.</p>',
      formule: 'Dans l\'attente du plaisir de vous accueillir, veuillez agréer l\'expression de nos salutations distinguées.',
      fonction_sig: 'Le Président'
    },
    'Réclamation': {
      salutation: 'Madame, Monsieur,',
      corps: '<p>Nous nous permettons de porter à votre attention <b>[objet de la réclamation]</b>.</p><p>En conséquence, nous vous prions de bien vouloir <b>[action attendue]</b> dans les meilleurs délais.</p>',
      formule: 'Dans l\'attente d\'une suite favorable, veuillez agréer l\'expression de nos salutations distinguées.',
      fonction_sig: 'Le Secrétaire Général'
    }
  };
  var tpl = templates[t];
  if(tpl && body_empty){
    frm.set_value('salutation', tpl.salutation);
    frm.set_value('corps', tpl.corps);
    frm.set_value('formule_politesse', tpl.formule);
    if(!frm.doc.fonction_signataire || frm.doc.fonction_signataire==='Le Secrétaire Général'){
      frm.set_value('fonction_signataire', tpl.fonction_sig);
    }
    frappe.show_alert({message: 'Modèle « '+t+' » pré-rempli. Complétez les champs entre crochets.', indicator:'green'});
  }
}

frappe.ui.form.on('Match', {
  after_save: function(frm){ recompute_stats_for_match(frm); }
});

async function recompute_stats_for_match(frm){
  let joueurs = new Set();
  (frm.doc.performances || []).forEach(function(r){ if(r.joueur) joueurs.add(r.joueur); });
  if(joueurs.size === 0){ return; }

  frappe.show_alert({message:'Mise à jour des statistiques...', indicator:'blue'});
  const token = frappe.csrf_token;

  async function apiGet(url){
    const r = await fetch(url, {headers:{'X-Frappe-CSRF-Token':token,'Accept':'application/json'}});
    const j = await r.json();
    return j.message;
  }

  for(const joueur of joueurs){
    try{
      // toutes les lignes de perf du joueur
      let url = '/api/method/frappe.client.get_list?doctype=' + encodeURIComponent('Performance Match Joueur') +
        '&parent=Match&limit_page_length=0' +
        '&filters=' + encodeURIComponent(JSON.stringify({joueur: joueur})) +
        '&fields=' + encodeURIComponent(JSON.stringify(['parent','buts','passes','cartons_jaunes','cartons_rouges','minutes']));
      let rows = await apiGet(url) || [];
      let parents = [...new Set(rows.map(r=>r.parent))];
      let statutMap = {};
      if(parents.length){
        let murl = '/api/method/frappe.client.get_list?doctype=Match&limit_page_length=0' +
          '&filters=' + encodeURIComponent(JSON.stringify([['name','in',parents]])) +
          '&fields=' + encodeURIComponent(JSON.stringify(['name','statut']));
        let matchs = await apiGet(murl) || [];
        matchs.forEach(m=> statutMap[m.name]=m.statut);
      }
      let joues = rows.filter(r=> statutMap[r.parent]==='Joué');
      let tb=0,tp=0,tcj=0,tcr=0,tmin=0;
      joues.forEach(function(r){ tb+=(r.buts||0); tp+=(r.passes||0); tcj+=(r.cartons_jaunes||0); tcr+=(r.cartons_rouges||0); tmin+=(r.minutes||0); });
      let nb = joues.length;
      let ratio = nb ? (tb/nb) : 0;
      await frappe.db.set_value('Joueur', joueur, {
        buts: tb, passes_decisives: tp, cartons_jaunes: tcj, cartons_rouges: tcr,
        minutes_jouees: tmin, matchs_joues: nb, ratio_buts: ratio
      });
    }catch(e){ console.error('maj stats '+joueur, e); }
  }
  frappe.show_alert({message:'Statistiques mises à jour ✔', indicator:'green'});
}

frappe.listview_settings['Match'] = frappe.listview_settings['Match'] || {};
frappe.listview_settings['Match'].onload = function(listview) {
    listview.page.add_inner_button(__('📅 Calendrier'), function() {
        frappe.set_route('List', 'Match', 'Calendar', 'Calendrier des Matchs');
    });
};
